using System;using System.Collections.Generic;using System.Runtime.Serialization;
namespace AshkanFitPro {
[DataContract] public class Member { [DataMember] public Guid Id {get;set;} [DataMember] public string Name {get;set;} [DataMember] public string Phone {get;set;} [DataMember] public string Plan {get;set;} [DataMember] public DateTime Start {get;set;} [DataMember] public DateTime Expiry {get;set;} [DataMember] public decimal Fee {get;set;} public string Status {get{return Expiry.Date<DateTime.Today?"Expired":"Active";}} }
[DataContract] public class Payment { [DataMember] public Guid Id {get;set;} [DataMember] public Guid MemberId {get;set;} [DataMember] public decimal Amount {get;set;} [DataMember] public DateTime Date {get;set;} [DataMember] public string Note {get;set;} }
[DataContract] public class Trainer { [DataMember] public Guid Id {get;set;} [DataMember] public string Name {get;set;} [DataMember] public string Specialty {get;set;} [DataMember] public string Phone {get;set;} }
[DataContract] public class Attendance { [DataMember] public Guid Id {get;set;} [DataMember] public Guid MemberId {get;set;} [DataMember] public DateTime CheckedInAt {get;set;} }
[DataContract] public class WorkoutPlan { [DataMember] public Guid Id {get;set;} [DataMember] public Guid MemberId {get;set;} [DataMember] public Guid TrainerId {get;set;} [DataMember] public string Goal {get;set;} [DataMember] public string Exercises {get;set;} [DataMember] public DateTime CreatedAt {get;set;} }
[DataContract] public class GymClass { [DataMember] public Guid Id {get;set;} [DataMember] public string Title {get;set;} [DataMember] public Guid TrainerId {get;set;} [DataMember] public DayOfWeek Day {get;set;} [DataMember] public string Time {get;set;} [DataMember] public int Capacity {get;set;} }
[DataContract] public class Expense { [DataMember] public Guid Id {get;set;} [DataMember] public DateTime Date {get;set;} [DataMember] public string Category {get;set;} [DataMember] public string Description {get;set;} [DataMember] public decimal Amount {get;set;} }
[DataContract] public class AuditEntry { [DataMember] public Guid Id {get;set;} [DataMember] public DateTime At {get;set;} [DataMember] public string Action {get;set;} [DataMember] public string Details {get;set;} }
[DataContract] public class BodyProgress { [DataMember] public Guid Id {get;set;} [DataMember] public Guid MemberId {get;set;} [DataMember] public DateTime RecordedAt {get;set;} [DataMember] public decimal WeightKg {get;set;} [DataMember] public decimal HeightCm {get;set;} [DataMember] public decimal WaistCm {get;set;} [DataMember] public decimal BodyFatPercent {get;set;} [DataMember] public string Goal {get;set;} public decimal Bmi {get {return HeightCm>0?Math.Round(WeightKg/((HeightCm/100m)*(HeightCm/100m)),1):0m;}} }
[DataContract] public class Store { [DataMember] public List<BodyProgress> BodyProgressRecords {get;set;} = new List<BodyProgress>(); [DataMember] public List<Member> Members {get;set;} = new List<Member>(); [DataMember] public List<Payment> Payments {get;set;} = new List<Payment>(); [DataMember] public List<Trainer> Trainers {get;set;} = new List<Trainer>(); [DataMember] public List<Attendance> AttendanceRecords {get;set;} = new List<Attendance>(); [DataMember] public List<WorkoutPlan> WorkoutPlans {get;set;} = new List<WorkoutPlan>(); [DataMember] public List<GymClass> Classes {get;set;} = new List<GymClass>(); [DataMember] public List<AuditEntry> AuditEntries {get;set;} = new List<AuditEntry>(); [DataMember] public List<Expense> Expenses {get;set;} = new List<Expense>(); }
}